    static void KindOf(IAssetBuilderPlugin original,TargetPlatform p) {
        bool big=p!=TargetPlatform.Win32;
        foreach(string field in new[]{"KindOf","BuildOnRequiredObjectKindOf"}) {
            int offset=field=="KindOf"?4:312;
            for(int i=0;i<KindNames.Length;++i) foreach(string prefix in new[]{"","+","-"}) {
                var b=Check(original,p,field+"='"+prefix+KindNames[i]+"'");int bit=KindValues[i];
                for(int word=0;word<9;++word) {
                    uint expected=bit>=0 && bit<284 && word==bit/32?1u<<(bit%32):0;
                    if(Word(b.InstanceData,1620+offset+4*word,big)!=expected)throw new System.Exception("Independent KindOf bit "+field+" "+prefix+KindNames[i]);
                }
            }
            foreach(string text in new[]{""," ","ALL","all","+ALL","-ALL","ALL -VEHICLE","-ALL AIRCRAFT","UNKNOWN","-UNKNOWN","VEHICLE -VEHICLE -VEHICLE","vehicle","+","-","VEHICLE AIRCRAFT STRUCTURE","VEHICLE, AIRCRAFT","INVALID"})Check(original,p,field+"='"+text+"'");
            var all=Check(original,p,field+"='ALL -VEHICLE'");
            for(int word=0;word<9;++word)if(Word(all.InstanceData,1620+offset+4*word,big)!=0xffffffffu)throw new System.Exception("ALL padding/pointer behavior");
            var unknown=Check(original,p,field+"='UNKNOWN'");
            if(Word(unknown.InstanceData,1620+offset+4*(149/32),big)!=(1u<<(149%32)))throw new System.Exception("KindOf unknown fallback");
        }
        Check(original,p,"KindOf='VEHICLE -VEHICLE' BuildOnRequiredObjectKindOf='ALL' Browser='a bb' Description='mask/list combined'");
    }
